// Reference data, read at build time. Everything here is regenerated by tools/ (see the update-theme-keys skill).
import keys from '@/data/keys.json'
import resolved from '@/data/resolved.json'
import tokens from '@/data/tokens.json'
import descriptions from '@/data/descriptions.json'
import tested from '@/data/tested.json'
import captures from '@/data/captures.json'
import examples from '@/data/examples.json'

export const BASES = [['dark', 'Ash'], ['darker', 'Dark'], ['light', 'Light'], ['midnight', 'Onyx']] as const
export type Base = (typeof BASES)[number][0]

export type Focus = { x: number; y: number; width: number; height: number }
export type Capture = { pixels: number; focus?: Focus; image: string; screen: string; width: number; height: number }
export type KeyEntry = {
	key: string
	area?: string
	description?: string
	image?: string
	screens?: string[]
	defaults: Partial<Record<Base, string>>
	raw?: Partial<Record<Base, string>>
}

export { keys, resolved, tokens, descriptions, tested, captures, examples }
